<?php
declare(strict_types=1);
define('STUDIO_SECTION_ENTRY',true);
require dirname(__DIR__).'/includes/header.php';
header('Content-Type: text/html; charset=UTF-8');
header('X-Robots-Tag: noindex, nofollow, noarchive');
header('Referrer-Policy: no-referrer');
header('X-Content-Type-Options: nosniff');
$data=json_decode((string)file_get_contents(dirname(__DIR__).'/includes/glossary.json'),true);
if(!is_array($data)){http_response_code(503);exit('Glosario temporalmente no disponible.');}
usort($data,fn($a,$b)=>strcasecmp($a['term'],$b['term']));
$categories=array_values(array_unique(array_column($data,'category')));sort($categories,SORT_STRING);
$base=studioBase();function e($x){return studioEsc($x);}
?><!doctype html><html lang="es-AR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title>Glosario cross · Studio</title><link rel="stylesheet" href="<?=e($base)?>assets/shared.css"><style>
:root{--ink:#492b47;--muted:#806478;--line:#efd5e4}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at top right,#f5d9f0,transparent 55%),#fff5fa;color:var(--ink);font:15px/1.6 system-ui,sans-serif}main{max-width:1150px;margin:auto;padding:24px 16px 50px}.hero{background:linear-gradient(120deg,#f9d3e8,#ecddf9);border-radius:23px;padding:26px;margin-bottom:18px}.eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:2px;color:#a13c78;font-weight:800}h1{font-size:clamp(29px,5vw,42px);letter-spacing:-1.5px;margin:5px 0 12px}h2{font-size:19px;margin:8px 0}.hero p,.meta{color:var(--muted)}p{margin:8px 0}.filters{display:grid;grid-template-columns:2fr 1fr;gap:12px;margin:15px 0}label{display:block;font-weight:650;margin-bottom:5px}input,select{width:100%;font:inherit;color:var(--ink);padding:11px;border:1px solid #dfbfd2;background:white;border-radius:10px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.term{background:#fffbfd;border:1px solid var(--line);padding:18px;border-radius:17px;box-shadow:0 5px 15px #92336309}.term[hidden]{display:none}.pill{display:inline-block;background:#f4e0ef;color:#883363;border-radius:99px;padding:3px 9px;font-size:11px;font-weight:700}.aliases{font-size:13px;color:var(--muted)}a{color:#95366d}a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #c479aa;outline-offset:2px}.footer{font-size:12px;color:var(--muted);margin-top:24px}@media(max-width:650px){.grid,.filters{grid-template-columns:1fr}.hero{padding:20px}}
</style></head><body><?=studioHeader('glosario')?><main><div class="hero"><div class="eyebrow">Studio · Biblioteca</div><h1>Glosario cross</h1><p>Un diccionario de términos de la comunidad, estilos, moda, maquillaje y presentación personal. No es un examen de identidad: cada persona elige cómo expresarse.</p><p><a href="<?=e($base)?>arcade/">Practicar con el desafío diario →</a></p></div><div class="filters"><div><label for="search">Buscar palabra o sinónimo</label><input id="search" type="search" placeholder="Ej.: en femme, stiletto, passing"></div><div><label for="category">Categoría</label><select id="category"><option value="">Todas las categorías</option><?php foreach($categories as $c):?><option value="<?=e($c)?>"><?=e($c)?></option><?php endforeach?></select></div></div><p class="meta" id="total" aria-live="polite"><?=count($data)?> términos</p><div class="grid" id="terms"><?php foreach($data as $row):?><article class="term" data-category="<?=e($row['category'])?>"><span class="pill"><?=e($row['category'])?></span><h2><?=e($row['term'])?></h2><p><?=e($row['definition'])?></p><?php if(!empty($row['aliases'])):?><p class="aliases">También: <?=e(implode(' · ',$row['aliases']))?></p><?php endif?></article><?php endforeach?></div><p id="empty" hidden>No encontramos términos con esa búsqueda.</p><div class="footer">Glosario editorial inicial, ampliable. Algunas expresiones cambian de significado según la comunidad y el contexto.</div></main><script>
'use strict';const search=document.getElementById('search'),category=document.getElementById('category'),terms=[...document.querySelectorAll('.term')];const norm=x=>String(x).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();function filter(){const q=norm(search.value),c=category.value;let n=0;for(const el of terms){const match=(!c||el.dataset.category===c)&&(!q||q.split(' ').every(w=>norm(el.textContent).includes(w)));el.hidden=!match;if(match)n++}document.getElementById('total').textContent=n+' de '+terms.length+' términos';document.getElementById('empty').hidden=n!==0}search.addEventListener('input',filter);category.addEventListener('change',filter);
</script></body></html>